import heapq

def match(orders):
    buy_book = []   # heap of (-price, arrival, id)
    sell_book = []  # heap of (price, arrival, id)
    order_info = {}
    trades = []
    arrival_counter = 0

    for o in orders:
        typ = o[0]
        if typ == 'cancel':
            oid = o[1]
            info = order_info.get(oid)
            if info and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        arrival = arrival_counter
        arrival_counter += 1
        remaining = qty
        info = {
            'side': side,
            'price': price,
            'qty': remaining,
            'arrival': arrival,
            'active': True,
            'type': typ
        }
        order_info[oid] = info

        opp_book = sell_book if side == 'buy' else buy_book

        while remaining > 0 and opp_book:
            top = opp_book[0]
            opp_price, opp_arrival, opp_id = top
            opp_info = order_info[opp_id]

            if (not opp_info['active']) or opp_info['qty'] <= 0:
                heapq.heappop(opp_book)
                continue

            if typ != 'market':
                if side == 'buy':
                    if opp_info['price'] > price:
                        break
                else:
                    if opp_info['price'] < price:
                        break

            trade_qty = min(remaining, opp_info['qty'])
            trade_price = opp_info['price']

            if side == 'buy':
                trades.append([oid, opp_id, trade_price, trade_qty])
            else:
                trades.append([opp_id, oid, trade_price, trade_qty])

            remaining -= trade_qty
            opp_info['qty'] -= trade_qty

            if opp_info['qty'] == 0:
                opp_info['active'] = False
                heapq.heappop(opp_book)

        info['qty'] = remaining

        if typ == 'limit' and remaining > 0:
            if side == 'buy':
                heapq.heappush(buy_book, (-price, arrival, oid))
            else:
                heapq.heappush(sell_book, (price, arrival, oid))
            if remaining < qty:
                pass
        else:
            info['active'] = False

    return trades

